module ULA(
input wire [31:0] IN_A,
input wire [31:0] IN_B,
input wire [2:0] IN_C,
output wire [31:0] OUT_A,
output wire ZERO
);
//RS
//RT
wire [31:0] DATA_RS;
wire [31:0] DATA_RT;
wire [2:0] ULA_CTRL;
reg [31:0] DATA_ALU_RESULT;
  assign DATA_RS = IN_A;
  assign DATA_RT = IN_B;
  assign ULA_CTRL = IN_C;
  assign ZERO = (DATA_ALU_RESULT == 32'h00000000) ? 1'b1 : 1'b0;
  //PARA A INSTRUO SLT, PEGA O SINAL DO RESULTADO DA SUBTRAO E ADICIONA AO FINAL DO VETOR
  assign OUT_A = ULA_CTRL == 3'b111 ? {28'h0000000,3'b000,DATA_ALU_RESULT[31]} : DATA_ALU_RESULT;
  always @(ULA_CTRL, DATA_RS, DATA_RT) begin
    case(ULA_CTRL)
    3'b000 : begin
      DATA_ALU_RESULT <= DATA_RS & DATA_RT;
      //AND
    end
    3'b001 : begin
      DATA_ALU_RESULT <= DATA_RS | DATA_RT;
      //OR
    end
    3'b010 : begin
      DATA_ALU_RESULT <= DATA_RS + DATA_RT;
      //ADD
    end
    3'b110 : begin
      DATA_ALU_RESULT <= DATA_RS - DATA_RT;
      //SUB
    end
    3'b111 : begin
      DATA_ALU_RESULT <= DATA_RS - DATA_RT;
      //SLT			
    end
    default : begin
      DATA_ALU_RESULT <= 32'h00000000;
    end
    endcase
  end
endmodule

