module procesoJugador(
input wire reset,
input wire clk,
input wire derecha,
input wire izquierda,
output reg [7:0] filasOut,
output reg [7:0] columnasOut
);
parameter [1:0]
  listo = 0,
  der = 1,
  izq = 2,
  presionado = 3;
reg [1:0] estado;
reg [7:0] filas;
reg [7:0] columnas;
  always @(posedge reset, posedge clk, posedge estado, posedge filas, posedge columnas) begin
    if(reset == 1'b1) begin
      columnas <= 8'b00001000;
      filas <= 8'b10000000;
    end else begin
      case(estado)
      der : begin
        columnas[7] <= columnas[0];
        columnas[6:0] <= columnas[7:1];
      end
      izq : begin
        columnas[7:1] <= columnas[6:0];
        columnas[0] <= columnas[7];
      end
      default : begin
        columnas <= columnas;
      end
      endcase
    end
  end
  always @(posedge reset, posedge clk, posedge estado, posedge derecha, posedge izquierda) begin
    if(reset == 1'b1) begin
      estado <= listo;
    end else begin
      if(estado == listo && derecha == 1'b1) begin
        estado <= der;
      end
      else if(estado == listo && izquierda == 1'b1) begin
        estado <= izq;
      end
      else if(estado == izq || estado == der) begin
        estado <= presionado;
      end
      else if(estado == presionado && izquierda == 1'b0 && derecha == 1'b0) begin
        estado <= listo;
      end
    end
  end
  always @(posedge reset, posedge clk, posedge filas, posedge columnas) begin
    if(reset == 1'b1) begin
      filasOut <= 8'b10000000;
      columnasOut <= 8'b00001000;
    end else begin
      filasOut <= filas;
      columnasOut <= columnas;
    end
  end
endmodule

