module uart_tx(
input wire Clk,
input wire Rst,
input wire FreqEn,
input wire [7:0] Byte,
input wire Kick,
output reg RsTx,
output wire Busy
);
// Operation:
// Wait for @Kick, save values of @Kick and @Byte when it's high.
// Transition between states when @FreqEn is high.
parameter [1:0]
  IDLE = 0,
  START = 1,
  XMIT = 2,
  STOP = 3;
reg [1:0] state; reg [1:0] NEXT_state;
reg [31:0] cnt; reg [31:0] NEXT_cnt;
reg [7:0] saveByte;
reg saveKick;
  assign Busy = saveKick;
  always @(state, cnt, saveByte, saveKick) begin
    NEXT_state <= state;
    NEXT_cnt <= cnt + 1;
    RsTx <= 1'b1;
    // high is idle
    case(state)
    IDLE : begin
      if(saveKick == 1'b1) begin
        NEXT_state <= START;
      end
    end
    START : begin
      NEXT_state <= XMIT;
      NEXT_cnt <= 0;
      RsTx <= 1'b0;
    end
    XMIT : begin
      RsTx <= saveByte[cnt];
      if(cnt == 7) begin
        NEXT_state <= STOP;
      end
    end
    STOP : begin
      // UART wants at least two stop bits - STOP, IDLE
      NEXT_state <= IDLE;
    end
    endcase
  end
  always @(posedge Clk) begin
    if(FreqEn == 1'b1) begin
      state <= NEXT_state;
      cnt <= NEXT_cnt;
      if(state == STOP) begin
        saveKick <= 1'b0;
      end
    end
    if(saveKick == 1'b0 && Kick == 1'b1) begin
      saveKick <= Kick;
      saveByte <= Byte;
    end
    if(Rst == 1'b1) begin
      state <= IDLE;
      saveKick <= 1'b0;
    end
  end
endmodule

