module pixel_counter(
input wire clk,
input wire hs,
input wire vs,
input wire vde,
output wire [15:0] pixel_x,
output wire [15:0] pixel_y
);
reg [15:0] x;
reg [15:0] y;
reg hs_prev;
reg vs_prev;
wire hs_rising;
wire vs_rising;
reg visible_row;
  always @(posedge clk) begin
    hs_prev <= hs;
    vs_prev <= vs;
    if((vs_rising == 1'b1)) begin
      // Clear Y count on vsync
      y <= {16{1'b0}};
    end
    else if((hs_rising == 1'b1)) begin
      // Clear X count on hsync
      x <= {16{1'b0}};
      // Clear visible row flag on hsync
      visible_row <= 1'b0;
      if((visible_row == 1'b1)) begin
        // Increment Y count on hsync only if a row was shown
        y <= y + 1;
      end
    end
    else if((vde == 1'b1)) begin
      // Increment the X count on visible video
      x <= x + 1;
      // Raise visible row flag
      visible_row <= 1'b1;
    end
  end
  // Edge Detection
  assign hs_rising = (hs_prev == 1'b0 && HS == 1'b1) ? 1'b1 : 1'b0;
  assign vs_rising = (vs_prev == 1'b0 && VS == 1'b1) ? 1'b1 : 1'b0;
  // Pixel Output
  assign pixel_x = x;
  assign pixel_y = y;
endmodule

