module eudet_tlu(
input wire clk_i,
input wire rst_n_i,
input wire eudet_trig_i,
input wire eudet_rst_i,
output wire eudet_busy_o,
output wire eudet_clk_o,
input wire busy_i,
input wire simple_mode_i,
input wire [15:0] deadtime_i,
output reg trig_o,
output wire rst_o,
output reg [15:0] trig_tag_o
);
// Sys connect
// Eudet signals
// From logic
// To logic
// Components
// constants
wire [31:0] C_DEADTIME = 2000;  // clk_i cycles
wire [31:0] C_CLKDIVIDER = 16;  // 160 MHz -> 10Mhz
// State machine
parameter [1:0]
  IDLE = 0,
  TRIGGER = 1,
  RECEIVE = 2,
  DEAD = 3;
reg [1:0] state;  // Sync inputs
wire sync_eudet_trig_t;
wire sync_eudet_rst_i;
reg [15:0] trig_tag_t;  // only 15:1 good
reg eudet_busy_t;
reg eudet_clk_t;
wire eudet_bust_t;
reg [7:0] clk_counter;
reg [4:0] bit_counter;
reg [15:0] dead_counter;
reg [15:0] deadtime_t;
  // Sync async inputs
  synchronizer trig_sync(
      .clk_i(clk_i),
    .rst_n_i(rst_n_i),
    .async_in(eudet_trig_i),
    .sync_out(sync_eudet_trig_t));
  synchronizer rst_sync(
      .clk_i(clk_i),
    .rst_n_i(rst_n_i),
    .async_in(eudet_rst_i),
    .sync_out(sync_eudet_rst_i));
  assign eudet_busy_o = eudet_busy_t;
  assign eudet_clk_o = eudet_clk_t;
  assign rst_o = 1'b0;
  always @(posedge clk_i, posedge rst_n_i) begin
    if((rst_n_i == 1'b0)) begin
      state <= IDLE;
      eudet_busy_t <= 1'b0;
      eudet_clk_t <= 1'b0;
      clk_counter <= {8{1'b0}};
      bit_counter <= {5{1'b0}};
      dead_counter <= {16{1'b0}};
      deadtime_t <= {16{1'b0}};
      trig_tag_t <= {16{1'b0}};
      trig_tag_o <= {16{1'b0}};
      trig_o <= 1'b0;
    end else begin
      case(state)
      IDLE : begin
        eudet_busy_t <= 1'b0;
        eudet_clk_t <= 1'b0;
        clk_counter <= {8{1'b0}};
        bit_counter <= {5{1'b0}};
        trig_o <= 1'b0;
        if((sync_eudet_trig_t == 1'b1)) begin
          state <= TRIGGER;
        end
      end
      TRIGGER : begin
        // Raise busy and wait until trigger is negated
        eudet_busy_t <= 1'b1;
        eudet_clk_t <= 1'b0;
        trig_o <= 1'b0;
        clk_counter <= {8{1'b0}};
        bit_counter <= {5{1'b0}};
        trig_tag_t <= {16{1'b0}};
        dead_counter <= {16{1'b0}};
        if((sync_eudet_trig_t == 1'b0 && simple_mode_i == 1'b0)) begin
          state <= RECEIVE;
        end
        else if((sync_eudet_trig_t == 1'b0 && simple_mode_i == 1'b1)) begin
          state <= DEAD;
        end
      end
      RECEIVE : begin
        eudet_busy_t <= 1'b1;
        trig_o <= 1'b0;
        clk_counter <= clk_counter + 1;
        dead_counter <= {16{1'b0}};
        if((clk_counter == (C_CLKDIVIDER - 1))) begin
          clk_counter <= {8{1'b0}};
          eudet_clk_t <=  ~eudet_clk_t;
          if((eudet_clk_t == 1'b1)) begin
            //sampling on negative edge
            bit_counter <= bit_counter + 1;
            trig_tag_t <= {eudet_trig_i,trig_tag_t[15:1]};
            // do not need synced vers here
          end
        end
        if((bit_counter == 5'b10000)) begin
          state <= DEAD;
          trig_tag_o <= {1'b0,trig_tag_t[14:0]};
        end
      end
      DEAD : begin
        eudet_busy_t <= 1'b1;
        eudet_clk_t <= 1'b0;
        trig_o <= 1'b0;
        if((dead_counter == 0)) begin
          trig_o <= 1'b1;
          // Trigger now (16 clock cycles after the initial trigger?)
        end
        dead_counter <= dead_counter + 1;
        if((dead_counter >= (deadtime_t) && busy_i == 1'b0)) begin
          state <= IDLE;
        end
      end
      default : begin
        eudet_busy_t <= 1'b0;
        eudet_clk_t <= 1'b0;
        trig_o <= 1'b0;
        clk_counter <= {8{1'b0}};
        bit_counter <= {5{1'b0}};
        state <= IDLE;
      end
      endcase
      deadtime_t <= deadtime_i;
    end
  end
endmodule

