  assign alpha3[1] = 1'b1;
  assign alpha3[2] = 1'b1;
  assign alpha4[0] = 1'b1;
  assign alpha4[1] = 1'b1;
  assign alpha4[2] = 1'b0;
  flipflop ff1(
