  assign Qp = Q2;
endmodule

module extRam_loader(
input wire clock,
input wire reset,
input wire [7:0] data_in,
input wire RxRdy_in,
output reg [15:0] data_out,
output reg RxRdy_out
);
parameter [0:0]
  LSB = 0,
  MSB = 1;
reg estado = LSB;
  always @(posedge clock, posedge reset) begin
      // reset
    if(reset == 1'b1) begin
      data_out <= {16{1'b0}};
      estado <= LSB;
      RxRdy_out <= 1'b0;
    end else begin
      RxRdy_out <= 1'b0;
      case(estado)
      LSB : begin
        if(RxRdy_in == 1'b1) begin
          // Modo lectura del LSB
          data_out[7:0] <= data_in;
          RxRdy_out <= 1'b0;
          estado <= MSB;
        end
      end
      MSB : begin
        if(RxRdy_in == 1'b1) begin
          data_out[15:8] <= data_in;
          RxRdy_out <= 1'b1;
          estado <= LSB;
        end
      end
      endcase
    end
  end
endmodule

