module uart(
output wire uart_tx,
input wire [7:0] data_in,
output reg ready,
input wire send_data,
input wire rst,
input wire clk
);
parameter [31:0] clk_freq=50000000;
parameter [31:0] baud_rate=115200;
parameter [1:0]
  reset = 0,
  waiting = 1,
  sending = 2;
reg [1:0] curr_state;
reg [31:0] clock_divide = 0;
reg slow_clock = 1'b0;
reg uart_tx_sig;
reg [31:0] current_bit;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      clock_divide <= 0;
      slow_clock <= 1'b0;
    end else begin
      clock_divide <= clock_divide + 1;
      if((clock_divide == 215)) begin
        // 651->38400 baud
        clock_divide <= 0;
        slow_clock <=  ~slow_clock;
      end
    end
  end
  always @(posedge slow_clock, posedge rst) begin
    if((rst == 1'b1)) begin
      curr_state <= reset;
    end else begin
      case(curr_state)
      reset : begin
        uart_tx_sig <= 1'b1;
        curr_state <= waiting;
      end
      waiting : begin
        ready <= 1'b1;
        current_bit <= 0;
        uart_tx_sig <= 1'b1;
        if((send_data == 1'b1)) begin
          curr_state <= sending;
        end
      end
      sending : begin
        ready <= 1'b0;
        current_bit <= current_bit + 1;
        if((current_bit == 9)) begin
          current_bit <= 0;
          uart_tx_sig <= 1'b1;
          curr_state <= waiting;
        end
        else if((current_bit == 0)) begin
          uart_tx_sig <= 1'b0;
        end
        else begin
          uart_tx_sig <= data_in[current_bit - 1];
        end
      end
      endcase
    end
  end
  assign uart_tx = uart_tx_sig;
endmodule

module hcc_divrnd(
input wire sysclk,
input wire reset,
input wire enable,
input wire signin,
input wire [13:1] exponentin,
input wire [53:1] mantissain,
input wire satin,
input wire zipin,
input wire nanin,
output wire signout,
output wire [11:1] exponentout,
output wire [52:1] mantissaout
);
// includes roundbit
wire [51:1] zerovec;
reg [2:1] signff;
reg satinff; reg zipinff; reg naninff;
reg overflowbitff;
reg [52:1] roundmantissaff; reg [52:1] mantissaff;
wire [13:1] exponentnode;
reg [13:1] exponentoneff;
reg [11:1] exponenttwoff;
wire [53:1] manoverflow;
wire [12:1] infinitygen;
wire [12:1] zerogen;
wire setmanzero; wire setmanmax;
wire setexpzero; wire setexpmax;
  genvar k;
  generate for (k=1; k <= 51; k = k + 1) begin: gzv
      assign zerovec[k] = 1'b0;
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      signff <= 2'b00;
      satinff <= 1'b0;
      zipinff <= 1'b0;
      naninff <= 1'b0;
      overflowbitff <= 1'b0;
      for (k=1; k <= 52; k = k + 1) begin
        roundmantissaff[k] <= 1'b0;
        mantissaff[k] <= 1'b0;
      end
      for (k=1; k <= 13; k = k + 1) begin
        exponentoneff[k] <= 1'b0;
      end
      for (k=1; k <= 11; k = k + 1) begin
        exponenttwoff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff[1] <= signin;
        signff[2] <= signff[1];
        satinff <= satin;
        zipinff <= zipin;
        naninff <= nanin;
        overflowbitff <= manoverflow[53];
        roundmantissaff <= mantissain[53:2] + ({zerovec,mantissain[1]});
        for (k=1; k <= 52; k = k + 1) begin
          mantissaff[k] <= (roundmantissaff[k] &  ~(setmanzero)) | setmanmax;
        end
        exponentoneff[13:1] <= exponentin[13:1];
        for (k=1; k <= 11; k = k + 1) begin
          exponenttwoff[k] <= (exponentnode[k] &  ~(setexpzero)) | setexpmax;
        end
      end
    end
  end
  assign exponentnode = exponentoneff[13:1] + ({zerovec[12:1],overflowbitff});
  //*********************************
  //*** PREDICT MANTISSA OVERFLOW ***   
  //*********************************
  assign manoverflow[1] = mantissain[1];
  genvar k;
  generate for (k=2; k <= 53; k = k + 1) begin: gmoa
      assign manoverflow[k] = manoverflow[k - 1] & mantissain[k];
  end
  endgenerate
  //**********************************
  //*** CHECK GENERATED CONDITIONS ***   
  //**********************************
  // '1' when true for all cases
  // infinity if exponent >= 255
  assign infinitygen[1] = exponentnode[1];
  genvar k;
  generate for (k=2; k <= 11; k = k + 1) begin: gia
      assign infinitygen[k] = infinitygen[k - 1] & exponentnode[k];
  end
  endgenerate
  // 12/05/09 - make sure exponentnode = -1 doesnt make infinity
  assign infinitygen[12] = (infinitygen[11] &  ~(exponentnode[12]) &  ~(exponentnode[13])) | satinff | (exponentnode[12] &  ~(exponentnode[13]));
  // '1' if infinity
  // zero if exponent <= 0
  assign zerogen[1] = exponentnode[1];
  genvar k;
  generate for (k=2; k <= 11; k = k + 1) begin: gza
      assign zerogen[k] = zerogen[k - 1] | exponentnode[k];
  end
  endgenerate
  assign zerogen[12] =  ~(zerogen[11]) | zipinff | exponentnode[13];
  // '1' if zero
  // set mantissa to 0 when infinity or zero condition
  assign setmanzero = infinitygen[12] | zerogen[12];
  assign setmanmax = naninff;
  // set exponent to 0 when zero condition 
  assign setexpzero = zerogen[12];
  // set exponent to "11..11" infinity
  assign setexpmax = infinitygen[12] | naninff;
  //***************
  //*** OUTPUTS ***
  //***************
  assign signout = signff[2];
  assign mantissaout = mantissaff;
  assign exponentout = exponenttwoff;
endmodule

