assign or_out = in | {100{select}};
assign xor_out = in ^ {100{select}};
assign comb_out = (select) ? (and_out[7:0] + or_out[7:0] + xor_out[7:0]) : (and_out[7:0] & or_out[7:0] & xor_out[7:0]);

// Pipeline stage 1
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        buffer_valid <= 1'b0;
    end else if (valid_a && ready_b) begin
        buffer_valid <= 1'b1;
        data_buffer <= comb_out;
    end else begin
        buffer_valid <= 1'b0;
    end
end

// Pipeline accumulator
reg [3:0] counter;
reg [9:0] accumulator;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 1'b0;
        accumulator <= 10'b0;
        counter <= 4'b0;
    end else if (buffer_valid && ready_b) begin
        if (counter == 4'b1111) begin
            valid_b <= 1'b1;
            accumulator <= accumulator + data_buffer;
            counter <= 4'b0;
        end else begin
            valid_b <= 1'b0;
            accumulator <= accumulator + data_buffer;
            counter <= counter + 1'b1;
        end
    end else begin
        valid_b <= 1'b0;
    end
end

// Output assignment
assign ready_a = ready_b;
assign data_out = accumulator;

endmodule

module dp_lsft64(
input wire [64:1] inbus,
input wire [6:1] shift,
output wire [64:1] outbus
);
wire [64:1] levzip; wire [64:1] levone; wire [64:1] levtwo; wire [64:1] levthr;
  assign levzip = inbus;
  genvar k;
  generate for (k=4; k <= 64; k = k + 1) begin: gla
      assign levone[k] = (levzip[k] &  ~(shift[2]) &  ~(shift[1])) | (levzip[k - 1] &  ~(shift[2]) & shift[1]) | (levzip[k - 2] & shift[2] &  ~(shift[1])) | (levzip[k - 3] & shift[2] & shift[1]);
  end
  endgenerate
  assign levone[3] = (levzip[3] &  ~(shift[2]) &  ~(shift[1])) | (levzip[2] &  ~(shift[2]) & shift[1]) | (levzip[1] & shift[2] &  ~(shift[1]));
  assign levone[2] = (levzip[2] &  ~(shift[2]) &  ~(shift[1])) | (levzip[1] &  ~(shift[2]) & shift[1]);
  assign levone[1] = levzip[1] &  ~(shift[2]) &  ~(shift[1]);
  genvar k;
  generate for (k=13; k <= 64; k = k + 1) begin: glba
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3])) | (levone[k - 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=9; k <= 12; k = k + 1) begin: glbb
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=5; k <= 8; k = k + 1) begin: glbc
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 4; k = k + 1) begin: glbd
      assign levtwo[k] = levone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: glca
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5])) | (levtwo[k - 48] & shift[6] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=33; k <= 48; k = k + 1) begin: glcb
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5]));
  end
  endgenerate
  genvar k;
  generate for (k=17; k <= 32; k = k + 1) begin: glcc
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 16; k = k + 1) begin: glcd
      assign levthr[k] = levtwo[k] &  ~(shift[6]) &  ~(shift[5]);
  end
  endgenerate
  assign outbus = levthr;
endmodule

