	  else
		   if (enable)
				case (etat)
					NO_MOTION: if (canRight) etat <= RIGHT;
					RIGHT:     if (~canRight) etat <= DOWN;
					DOWN:      if (canLeft) etat <= LEFT;
							     else if (canRight) etat <= RIGHT;
								  else etat <= NO_MOTION;
					LEFT:      if (~canLeft) etat <= DOWN;
					default:   etat <= NO_MOTION;
				endcase
	end

	always @(etat) begin
		case (etat)
			NO_MOTION: Motion = 3'b000;
			RIGHT:     Motion = 3'b100;
