module ALU(
input wire [31:0] ope1,
input wire [31:0] ope2,
input wire [5:0] aluop,
input wire carry,
output reg [31:0] alurs
);
  always @(ope1, ope2, aluop, carry) begin
    case(aluop)
        // ADD
    6'b100000 : begin
      alurs <= ope1 + ope2;
      // ADDcc
    end
    6'b100001 : begin
      alurs <= ope1 + ope2;
      // ADDX
    end
    6'b100010 : begin
      alurs <= ope1 + ope2 + carry;
      //ADDXcc
    end
    6'b100011 : begin
      alurs <= ope1 + ope2 + carry;
      // SUB
    end
    6'b100100 : begin
      alurs <= ope1 - ope2;
      // SUBcc
    end
    6'b100101 : begin
      alurs <= ope1 - ope2;
      // SUBX
    end
    6'b100110 : begin
      alurs <= ope1 - ope2 - carry;
      //SUBXcc
    end
    6'b100111 : begin
      alurs <= ope1 - ope2 - carry;
      // AND
    end
    6'b101000 : begin
      alurs <= ope1 & ope2;
      // ANDcc
    end
    6'b101001 : begin
      alurs <= ope1 & ope2;
      // ANDN
    end
    6'b101010 : begin
      alurs <=  ~(ope1 & ope2);
      // ANDNcc
    end
    6'b101011 : begin
      alurs <=  ~(ope1 & ope2);
      // OR
    end
    6'b101100 : begin
      alurs <= ope1 | ope2;
      // ORcc
    end
    6'b101101 : begin
      alurs <= ope1 | ope2;
      // ORN
    end
    6'b101110 : begin
      alurs <=  ~(ope1 | ope2);
      // ORNcc
    end
    6'b101111 : begin
      alurs <=  ~(ope1 | ope2);
      // XOR
    end
    6'b110000 : begin
      alurs <= ope1 ^ ope2;
      // XORcc
    end
    6'b110001 : begin
      alurs <= ope1 ^ ope2;
      // XNOR
    end
    6'b110010 : begin
      alurs <=  ~(ope1 ^ ope2);
      // XNORcc
    end
    6'b110011 : begin
      alurs <=  ~(ope1 ^ ope2);
      //SAVE 57
    end
    6'b111001 : begin
      alurs <= ope1 + ope2;
      //RESTORE 58
    end
    6'b111010 : begin
      alurs <= ope1 + ope2;
    end
    default : begin
      alurs <= {32{1'b0}};
    end
    endcase
  end
endmodule

