module fp_lnclz(
input wire [32:1] mantissa,
output wire [5:1] leading
);
wire [5:1] position[6:1]; wire [5:1] positionmux[6:1];
wire [6:1] zerogroup; wire [6:1] firstzero;
wire [6:1] lastman;
  assign zerogroup[1] = mantissa[32] | mantissa[31] | mantissa[30] | mantissa[29] | mantissa[28] | mantissa[27];
  assign zerogroup[2] = mantissa[26] | mantissa[25] | mantissa[24] | mantissa[23] | mantissa[22] | mantissa[21];
  assign zerogroup[3] = mantissa[20] | mantissa[19] | mantissa[18] | mantissa[17] | mantissa[16] | mantissa[15];
  assign zerogroup[4] = mantissa[14] | mantissa[13] | mantissa[12] | mantissa[11] | mantissa[10] | mantissa[9];
  assign zerogroup[5] = mantissa[8] | mantissa[7] | mantissa[6] | mantissa[5] | mantissa[4] | mantissa[3];
  assign zerogroup[6] = mantissa[2] | mantissa[1];
  fp_pos #(
      .start(0))
  pa(
      .ingroup(mantissa[32:27]),
    .position(position[1][5:1]));
  fp_pos #(
      .start(6))
  pb(
      .ingroup(mantissa[26:21]),
    .position(position[2][5:1]));
  fp_pos #(
      .start(12))
  pc(
      .ingroup(mantissa[20:15]),
    .position(position[3][5:1]));
  fp_pos #(
      .start(18))
  pd(
      .ingroup(mantissa[14:9]),
    .position(position[4][5:1]));
  fp_pos #(
      .start(24))
  pe(
      .ingroup(mantissa[8:3]),
    .position(position[5][5:1]));
  fp_pos #(
      .start(30))
  pf(
      .ingroup(lastman),
    .position(position[6][5:1]));
  assign lastman = {mantissa[2:1],4'b0000};
  assign firstzero[1] = zerogroup[1];
  assign firstzero[2] =  ~(zerogroup[1]) & zerogroup[2];
  assign firstzero[3] =  ~(zerogroup[1]) &  ~(zerogroup[2]) & zerogroup[3];
  assign firstzero[4] =  ~(zerogroup[1]) &  ~(zerogroup[2]) &  ~(zerogroup[3]) & zerogroup[4];
  assign firstzero[5] =  ~(zerogroup[1]) &  ~(zerogroup[2]) &  ~(zerogroup[3]) &  ~(zerogroup[4]) & zerogroup[5];
  assign firstzero[6] =  ~(zerogroup[1]) &  ~(zerogroup[2]) &  ~(zerogroup[3]) &  ~(zerogroup[4]) &  ~(zerogroup[5]) & zerogroup[6];
  genvar k;
  generate for (k=1; k <= 5; k = k + 1) begin: gma
      assign positionmux[1][k] = position[1][k] & firstzero[1];
    genvar j;
    generate for (j=2; j <= 6; j = j + 1) begin: gmb
          assign positionmux[j][k] = positionmux[j - 1][k] | (position[j][k] & firstzero[j]);
    end
    endgenerate
  end
  endgenerate
  assign leading = positionmux[6][5:1];
endmodule

