// Kolonnas piksela koordinatas
// pirma poga
// Sarkana krasa
// Zala krasa
// Zila krasa
  always @(disp_ena, row, column, BUTTON_1) begin : P1
    reg [31:0] column_int = column;
  // Tiek salidzinats ar INTEGER
    reg [31:0] row_int = row;
  // vertibu, tapec japarveido uz UNSIGNED INTEGER
    reg [31:0] crossValX = 320;
  // Zilaa krusta rindas un kolonnas koordinatas.
