module HammingCodeLEDs(
input wire enc,
input wire [7:1] data,
output reg [3:1] pout
);
// Encode switch [SW0]
// Data bits [SW(7:1)]
// Parity bits [LD(2:0)]
reg [3:1] parity;
  always @(enc) begin
    if((enc == 1'b1)) begin
      // encode: compute and display parity bits
      parity[1] <= data[3] ^ data[5] ^ data[7];
      parity[2] <= data[3] ^ data[6] ^ data[7];
      parity[3] <= data[5] ^ data[6] ^ data[7];
    end
    else begin
      // decode: compute and display error syndrome
      parity[1] <= data[1] ^ data[3] ^ data[5] ^ data[7];
      parity[2] <= data[2] ^ data[3] ^ data[6] ^ data[7];
      parity[3] <= data[4] ^ data[5] ^ data[6] ^ data[7];
    end
    pout <= parity;
    // Output parity bits to LEDs
  end
endmodule

