module i2c_arbiter_ss_detector(
input wire clk_i,
input wire rst_n_i,
input wire input_sda_i,
input wire input_scl_i,
input wire start_ack_i,
input wire stop_ack_i,
output reg start_state_o,
output reg stop_state_o
);
// Clock & Reset
// I2C input buses & ACK
// Start/Stop outputs
// Start FSM signals
parameter [1:0]
  ARB_START_IDLE = 0,
  ARB_START_WAIT_SDA = 1,
  ARB_START_DETECTED = 2;
reg [1:0] arb_start_st = ARB_START_IDLE;  // Stop FSM signals
parameter [1:0]
  ARB_STOP_IDLE = 0,
  ARB_STOP_WAIT_SDA = 1,
  ARB_STOP_DETECTED = 2;
reg [1:0] arb_stop_st = ARB_STOP_IDLE;
  // Start FSM
  always @(posedge clk_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      arb_start_st <= ARB_START_IDLE;
      start_state_o <= 1'b0;
    end
    else begin
      case(arb_start_st)
      ARB_START_IDLE : begin
        start_state_o <= 1'b0;
        if(input_sda_i == 1'b1 && input_scl_i == 1'b1) begin
          arb_start_st <= ARB_START_WAIT_SDA;
        end
      end
      ARB_START_WAIT_SDA : begin
        if(input_scl_i == 1'b1) begin
          if(input_sda_i == 1'b0) begin
            start_state_o <= 1'b1;
            arb_start_st <= ARB_START_DETECTED;
          end
        end
        else begin
          start_state_o <= 1'b0;
          arb_start_st <= ARB_START_IDLE;
        end
      end
      ARB_START_DETECTED : begin
        if(start_ack_i == 1'b1) begin
          start_state_o <= 1'b0;
          arb_start_st <= ARB_START_IDLE;
        end
      end
      default : begin
        start_state_o <= 1'b0;
        arb_start_st <= ARB_START_IDLE;
      end
      endcase
    end
  end
  // Stop FSM
  always @(posedge clk_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      arb_stop_st <= ARB_STOP_IDLE;
      stop_state_o <= 1'b0;
    end
    else begin
      case(arb_stop_st)
      ARB_STOP_IDLE : begin
        stop_state_o <= 1'b0;
        if(input_scl_i == 1'b1 && input_sda_i == 1'b0) begin
          arb_stop_st <= ARB_STOP_WAIT_SDA;
        end
      end
      ARB_STOP_WAIT_SDA : begin
        if(input_scl_i == 1'b1) begin
          if(input_sda_i == 1'b1) begin
            stop_state_o <= 1'b1;
            arb_stop_st <= ARB_STOP_DETECTED;
          end
        end
        else begin
          stop_state_o <= 1'b0;
          arb_stop_st <= ARB_STOP_IDLE;
        end
      end
      ARB_STOP_DETECTED : begin
        if(stop_ack_i == 1'b1) begin
          stop_state_o <= 1'b0;
          arb_stop_st <= ARB_STOP_IDLE;
        end
      end
      default : begin
        stop_state_o <= 1'b0;
        arb_stop_st <= ARB_STOP_IDLE;
      end
      endcase
    end
  end
endmodule

