module SEE_det(
input wire clk,
input wire rst,
input wire data0,
input wire data1,
output wire EGDE,
output wire F_EGDE,
output wire EOP
);
// data0 = data+, data1 = data-
// general egde for everything
// falling egde for starting condition
// end of packet dtection
reg cur_EOP; wire nxt_EOP;
reg cur_EGDE; wire nxt_EGDE;
reg cur_FEGDE; wire nxt_FEGDE;  // flip flop all output signals
reg d1; reg d2;  // input edge detection flip-flop
  assign EGDE = cur_EGDE;
  assign F_EGDE = cur_FEGDE;
  assign EOP = cur_EOP;
  always @(posedge clk, posedge rst) begin : P1
  // overall process for clock
    if(rst == 1'b0) begin
      cur_EOP <= 1'b0;
      cur_EGDE <= 1'b0;
      cur_FEGDE <= 1'b0;
      d1 <= 1'b1;
      d2 <= 1'b1;
    end else begin
      d1 <= data0;
      d2 <= d1;
      cur_EOP <= nxt_EOP;
      cur_EGDE <= nxt_EGDE;
      cur_FEGDE <= nxt_FEGDE;
    end
  end
  assign nxt_EGDE = rst == 1'b1 ? d1 ^ d2 : 1'b0;
  // edge detection, for re-synchronizing signals
  assign nxt_FEGDE = rst == 1'b1 ? d2 & ( ~d1) : 1'b0;
  // falling edge only
  assign nxt_EOP = rst == 1'b1 ?  ~(data0 | data1) : 1'b0;
    // since USB will not keep sending EOP, so a combinational will be sufficient.
endmodule

