module Instruction_Register(
input wire clk,
input wire reset,
input wire enb,
input wire [1:0] func,
input wire [11:0] IR_in,
output wire [11:0] IR_out
);
// ufix2
// ufix12
// ufix12
// Signals
wire [1:0] func_unsigned;  // ufix2
wire [11:0] IR_in_unsigned;  // ufix12
reg [11:0] IR_out_tmp;  // ufix12
reg [11:0] IR_value;  // ufix12
reg [11:0] IR_value_next;  // ufix12
  assign func_unsigned = func;
  assign IR_in_unsigned = IR_in;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      IR_value <= 0;
    end else begin
      if(enb == 1'b1) begin
        IR_value <= IR_value_next;
      end
    end
  end
  always @(func_unsigned, IR_in_unsigned, IR_value) begin
    IR_value_next <= IR_value;
    //MATLAB Function 'CPU_Subsystem_8_bit/Instruction Register': '<S8>:1'
    // A 12-bit Instruction Register with the following func:
    // func == 0 => reset
    // func == 1 => store into IR
    // func == 2 => read from IR;
    // otherwise, preserve old value and return 0
    // HDL specific fimath
    //'<S8>:1:22'
    IR_out_tmp <= 0;
    case(func_unsigned)
    2'b00 : begin
      // reset
      //'<S8>:1:27'
      IR_value_next <= 0;
    end
    2'b01 : begin
      // store into IR
      //'<S8>:1:30'
      IR_value_next <= IR_in_unsigned;
    end
    2'b10 : begin
      // read IR
      //'<S8>:1:33'
      IR_out_tmp <= IR_value;
    end
    default : begin
    end
    endcase
  end
  assign IR_out = IR_out_tmp;
endmodule

