parameter v_discharge = 3.5; // voltage threshold for discharging the battery
parameter r_charge = 100; // charging resistance of the battery
parameter r_discharge = 50; // discharging resistance of the battery
parameter c_capacity = 1000; // capacity of the battery

reg charge_enable_reg;
reg discharge_enable_reg;

assign charge_enable = charge_enable_reg;
assign discharge_enable = discharge_enable_reg;

wire charging_current = charge_enable_reg * voltage / r_charge;
wire discharging_current = discharge_enable_reg * voltage / r_discharge;

always @(*) begin
