module hcc_alulong(
input wire sysclk,
input wire reset,
input wire enable,
input wire addsub,
input wire [32:1] aa,
input wire [32:1] bb,
output wire [32:1] cc
);
wire [31:1] zerovec;
wire [32:1] bbvec;
reg [32:1] aluff;
  genvar k;
  generate for (k=1; k <= 31; k = k + 1) begin: gza
      assign zerovec[k] = 1'b0;
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 32; k = k + 1) begin: gaa
      assign bbvec[k] = bb[k] ^ addsub;
  end
  endgenerate
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 32; k = k + 1) begin
        aluff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        aluff <= aa + bbvec + ({zerovec,addsub});
      end
    end
  end
  assign cc = aluff;
endmodule

