module gc_pulse_synchronizer(
input wire clk_in_i,
input wire clk_out_i,
input wire rst_n_i,
output wire d_ready_o,
input wire d_p_i,
output reg q_p_o
);
// pulse input clock
// pulse output clock
// system reset (clk_in_i domain)
// pulse input ready (clk_in_i domain). When HI, a pulse coming to d_p_i will be
// correctly transferred to q_p_o.
// pulse input (clk_in_i domain)
// pulse output (clk_out_i domain)
parameter c_sync_stages = 3;
reg ready; reg d_p_d0;
reg in_ext; reg out_ext;
wire out_feedback;
reg [c_sync_stages - 1:0] d_in2out;
reg [c_sync_stages - 1:0] d_out2in;
  // rtl
  always @(posedge clk_out_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      d_in2out <= {((c_sync_stages - 1)-(0)+1){1'b0}};
      out_ext <= 1'b0;
    end else begin
      d_in2out <= {d_in2out[c_sync_stages - 2:0],in_ext};
      out_ext <= d_in2out[c_sync_stages - 1];
    end
  end
  always @(posedge clk_in_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      d_out2in <= {((c_sync_stages - 1)-(0)+1){1'b0}};
    end else begin
      d_out2in <= {d_out2in[c_sync_stages - 2:0],out_ext};
    end
  end
  assign out_feedback = d_out2in[c_sync_stages - 1];
  always @(posedge clk_in_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      ready <= 1'b1;
      in_ext <= 1'b0;
      d_p_d0 <= 1'b0;
    end else begin
      d_p_d0 <= d_p_i;
      if((ready == 1'b1 && d_p_i == 1'b1 && d_p_d0 == 1'b0)) begin
        in_ext <= 1'b1;
        ready <= 1'b0;
      end
      else if((in_ext == 1'b1 && out_feedback == 1'b1)) begin
        in_ext <= 1'b0;
      end
      else if((in_ext == 1'b0 && out_feedback == 1'b0)) begin
        ready <= 1'b1;
      end
    end
  end
  always @(posedge clk_out_i, posedge rst_n_i) begin
    if(rst_n_i == 1'b0) begin
      q_p_o <= 1'b0;
    end else begin
      q_p_o <=  ~out_ext & d_in2out[c_sync_stages - 1];
    end
  end
  assign d_ready_o = ready;
endmodule

